// The MuleSoo agency credit for jsPDF documents — the one-line lockup
// ("Designed & built by MuleSoo Digital Services · mulesoo.com"), centred at
// the foot of the page: the exact arrangement on the member ID card, which is
// the reference and lives in idcard.js (canvas) — do not restyle either to
// match the other; they already match.
//
// The artwork is embedded as base64 so stamping is synchronous and works even
// offline — no fetch, no async, no caller-signature changes. Sized relative to
// the page so the same call is correct in pt- and mm-unit documents alike
// (0.39 × width ≈ 82mm on A4; bottom margin ≈ 10mm).
const ASPECT = 11.923; // native pixel aspect of the lockup — never distort it

const CREDIT_COMPACT_ON_LIGHT =
  'data:image/png;base64,';

/**
 * Stamp the credit at the bottom-centre of the CURRENT page.
 * Returns the rectangle it occupied so callers can keep footer text clear.
 */
export function stampMulesooCredit(doc) {
  const W = doc.internal.pageSize.getWidth();
  const H = doc.internal.pageSize.getHeight();
  const w = W * 0.39;
  const h = w / ASPECT;
  const x = (W - w) / 2;
  const y = H - H * 0.034 - h;
  doc.addImage(CREDIT_COMPACT_ON_LIGHT, 'PNG', x, y, w, h, undefined, 'FAST');
  return { x, y, w, h };
}
